<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Receipt {{ $payment->receipt_number }}</title><style>body{font-family:Arial,sans-serif;color:#111;margin:0}.receipt{max-width:720px;margin:40px auto;padding:32px;border:1px solid #ddd}.top{display:flex;justify-content:space-between;gap:20px;border-bottom:2px solid #111;padding-bottom:20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:24px}.label{font-size:12px;color:#666;text-transform:uppercase}.value{font-weight:bold;margin-top:4px}.amount{font-size:28px}.reversed{padding:12px;background:#fee2e2;color:#991b1b;margin-top:20px;font-weight:bold}@media print{button{display:none}.receipt{border:0;margin:0;max-width:none}}</style></head><body><main class="receipt"><div class="top"><div><h1>Payment receipt</h1><div>{{ $payment->receipt_number }}</div></div><button onclick="window.print()">Print</button></div>@if($payment->is_reversed)<div class="reversed">REVERSED — {{ $payment->reversal_reason }}</div>@endif<div class="grid"><div><div class="label">Customer</div><div class="value">{{ $payment->account->application->first_name }} {{ $payment->account->application->last_name }}</div></div><div><div class="label">Payment date</div><div class="value">{{ $payment->paid_at->format('M j, Y H:i') }}</div></div><div><div class="label">Account</div><div class="value">{{ $payment->account->account_number }}</div></div><div><div class="label">Application</div><div class="value">{{ $payment->account->application->application_number }}</div></div><div><div class="label">Product</div><div class="value">{{ $payment->account->application->product_name_snapshot }}</div></div><div><div class="label">Method</div><div class="value">{{ str($payment->payment_method)->replace('_',' ')->headline() }}</div></div><div><div class="label">Amount</div><div class="value amount">{{ number_format($payment->amount_cents/100, 2) }} {{ $payment->account->currency }}</div></div>